package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="two_factor_challenges") public class TwoFactorChallenge { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,length=10) private String code; @Column(nullable=false) private LocalDateTime expiresAt; @Column(nullable=false) private boolean used=false; public TwoFactorChallenge(){} public TwoFactorChallenge(User u,String c,LocalDateTime e){user=u;code=c;expiresAt=e;} public Long getId(){return id;} public User getUser(){return user;} public String getCode(){return code;} public LocalDateTime getExpiresAt(){return expiresAt;} public boolean isUsed(){return used;} public void setUsed(boolean v){used=v;} }
